class BankAccount:
    """Represents a bank account with methods for depositing and withdrawing money."""

    def __init__(self, balance=0):
        """Initialize the bank account with a given balance or zero if no balance is provided."""
        self.balance = balance

    def deposit(self, amount):
        """Deposit the given amount into the bank account and update the balance."""
        if amount > 0:
            self.balance += amount
            print(f"Deposit: {amount}, Balance: {self.balance}")
        else:
            print("Error: Cannot deposit a negative amount.")

    def withdraw(self, amount):
        """Withdraw the given amount from the bank account and update the balance."""
        if amount > 0 and self.balance >= amount:
            self.balance -= amount
            print(f"Withdraw: {amount}, Balance: {self.balance}")
        else:
            print("Error: Cannot withdraw a negative amount or insufficient funds.")


# Example usage
account = BankAccount()

while True:
    print("Menu:")
    print("1. Deposit")
    print("2. Withdraw")
    print("3. Balance")
    print("4. Exit")

    choice = int(input("Enter your choice: "))

    if choice == 1:
        deposit_amount = float(input("Enter the amount to deposit: "))
        account.deposit(deposit_amount)

    elif choice == 2:
        withdraw_amount = float(input("Enter the amount to withdraw: "))
        account.withdraw(withdraw_amount)

    elif choice == 3:
        print(f"Balance: {account.balance}")

    elif choice == 4:
        print("Exiting the program...")
        break

    else:
        print("Error: Invalid choice. Please try again.")
```

This program allows the user to perform various operations on the bank account and provides a user-friendly interface for making deposits and withdrawals.
